const $=s=>document.querySelector(s);const safe=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const read=(k,d)=>{try{return JSON.parse(localStorage.getItem(k))||d}catch{return d}};const save=(k,v)=>{try{localStorage.setItem(k,JSON.stringify(v))}catch{toast('이 브라우저에서 저장을 사용할 수 없습니다.')}};
const roles=[['마케팅','◎'],['상품·디자인','◇'],['온라인MD','▤'],['영업','▥'],['CRM·CS','♡'],['물류','▣'],['인사','♧'],['재무·IT','⌘'],['전체','✧']];
const base=[{id:1,name:'브랜드 콘텐츠 메이커',role:'마케팅',icon:'✦',desc:'상품의 매력을 브랜드 언어로. SNS 카피와 캠페인 메시지 초안을 만듭니다.',owner:'마케팅팀',sample:'로즈골드 목걸이 / 출근룩을 위한 데일리 주얼리 / 인스타그램',result:'[인스타그램 카피 예시]\n매일의 나에게, 은은한 빛 한 조각.\n단정한 셔츠에도 편안한 니트에도, 로즈골드로 완성하는 오늘의 무드.\n\n[콘텐츠 구성]\n1. 착용 디테일 컷\n2. 데일리 스타일링 제안\n3. 상품 정보 확인 안내\n\n※ 소재·가격·프로모션은 상품 담당자 확인 후 게시합니다.'},{id:2,name:'상품 인사이트 어시스턴트',role:'상품·디자인',icon:'◇',desc:'고객 리뷰에서 다음 상품의 힌트를. 니즈와 개선 포인트를 정리합니다.',owner:'상품기획팀',sample:'[가상 리뷰] 디자인이 예뻐요. 잠금장치가 조금 불편해요. 선물 포장이 좋아요.',result:'[가상 리뷰 분석 예시]\n• 선호 요인: 디자인, 선물 포장\n• 개선 후보: 잠금장치 사용성\n• 후속 과제: 반복 언급 빈도 확인 및 실제 착용 테스트\n\n표본이 적어 전체 고객 의견으로 일반화할 수 없습니다.'},{id:3,name:'고객 응대 파트너',role:'CRM·CS',icon:'♡',desc:'문의의 맥락을 읽고 브랜드 톤으로. 확인할 정보와 답변 초안을 제안합니다.',owner:'CS팀',sample:'선물 받은 목걸이의 체인 길이를 조절할 수 있는지 문의가 들어왔습니다.',result:'[응대 초안 예시]\n안녕하세요, 제이에스티나입니다.\n체인 길이 조절 가능 여부는 상품에 따라 다를 수 있어 상품명 또는 품번을 알려주시면 확인 후 안내드리겠습니다.\n\n[담당자 확인]\n품번, 수선 정책, 비용, 접수 방식 및 예상 소요 기간\n※ 확인되지 않은 수선 가능 여부나 비용은 확정 안내하지 않습니다.'},{id:4,name:'상세페이지 카피 스튜디오',role:'온라인MD',icon:'▤',desc:'핵심 특징부터 구매 포인트까지. 채널에 맞는 상품 설명의 뼈대를 잡습니다.',owner:'온라인사업팀',sample:'미니 크로스백 / 가벼운 외출 / 데일리 스타일 / 상세페이지',result:'[상세페이지 구성 예시]\n헤드라인: 가벼운 외출, 나다운 스타일\n핵심 메시지: 일상에 자연스럽게 어울리는 미니 크로스백\n구성: 전체 이미지 → 수납 상세 → 착용 컷 → 규격 및 주의사항\n\n소재·중량·크기·수납 성능은 검증된 상품 정보로 보완하세요.'},{id:5,name:'인사 문서 코파일럿',role:'인사',icon:'♧',desc:'공지와 교육 기획 초안을 빠르게. 구성원에게 명확하게 전달하는 문서를 돕습니다.',owner:'인사팀',sample:'AI 실무 워크숍 / 희망자 모집 / 일시와 장소는 추후 안내',result:'[공지 초안 예시]\n제목: AI 실무 워크숍 참여 희망자 모집\n\n실제 업무에 AI를 활용해 보고 싶은 구성원을 모집합니다. 반복 업무 사례를 바탕으로 함께 실습할 예정입니다.\n• 대상: 참여 희망 구성원\n• 일정 및 장소: 추후 안내\n• 준비: 개선하고 싶은 업무 사례 1개\n\n접수 방법과 마감일은 담당자 확인 후 추가합니다.'},{id:6,name:'매장 운영 브리핑',role:'영업',icon:'▥',desc:'매장의 일일 메모를 한눈에. 고객 반응과 후속 조치로 나눠 정리합니다.',owner:'영업팀',sample:'신상품 문의 증가 / 특정 컬러 재고 확인 요청 / 주말 행사 준비 필요',result:'[운영 브리핑 예시]\n고객 반응: 신상품 관심 확인\n재고 확인: 문의 컬러의 매장별 가용 재고 조회 필요\n실행 과제: 주말 행사 준비 사항 및 담당자 확인\n\n실제 판매 및 재고 데이터는 연결되지 않았습니다.'},{id:7,name:'물류 이슈 정리 도우미',role:'물류',icon:'▣',desc:'출고·반품 메모를 유형별로. 처리 우선순위와 확인 목록을 작성합니다.',owner:'물류팀',sample:'주소 확인 필요 2건 / 반품 검수 대기 3건 / 가상 데이터',result:'[물류 체크리스트 예시]\n1. 주소 확인 건: 개인정보 노출 없이 주문 식별자로 담당자 확인\n2. 반품 검수: 상태 확인 및 검수 결과 기록\n3. 미처리 건: 마감 시점에 담당자 재확인\n\n실제 주문 처리나 출고 변경은 수행하지 않습니다.'},{id:8,name:'경영 보고 구조화 도우미',role:'재무·IT',icon:'⌘',desc:'보고 메모를 의사결정 중심으로. 현황·이슈·검토 과제로 구조화합니다.',owner:'경영지원',sample:'시스템 연동 검토 / 공급사 API 확인 필요 / 예산 미확정',result:'[보고 구조 예시]\n현황: 사내 시스템 연동 가능성 검토 단계\n이슈: API 지원 범위와 비용 미확정\n검토 과제: 공급사 기술 협의 및 요구사항 정리\n의사결정: 시범 범위 선정 후 견적 요청 여부\n\nERP 원장 및 재무 수치는 조회하지 않습니다.'}];
let agents=[...base,...read('j-ax-agents',[])],favorites=read('j-ax-favs',[]),role='마케팅',onlyFav=false,query='',view='home';
let posts=[...read('j-ax-posts',[]),{title:'상품 설명 초안, 브랜드 톤을 유지하는 프롬프트',type:'활용 노하우',team:'온라인MD',body:'샘플 경험입니다.\n\n상품 정보를 먼저 정리하고, 금지 표현과 브랜드 톤을 함께 전달하는 흐름을 제안합니다. 소재·효능 등 확인되지 않은 속성이 추가되지 않았는지 담당자가 검토합니다.'},{title:'반복 업무를 에이전트로 바꾸기 전에 묻는 3가지',type:'에이전트 만들기',team:'AX 추진',body:'샘플 학습 콘텐츠입니다.\n\n① 반복되는 입력과 출력은 무엇인가?\n② 판단이 필요한 지점은 어디인가?\n③ 누가 결과를 확인하고 승인하는가?\n\n작은 업무 한 개부터 흐름을 정의해 보세요.'},{title:'AI 결과를 그대로 쓰기 전에, 우리 팀의 검토 기준',type:'함께 배우기',team:'인사팀',body:'샘플 가이드입니다.\n\n수치·원문 출처·브랜드 표현·개인정보를 확인하세요. 실제 적용 전 사내 AI 활용 기준을 확정해야 합니다.'}];
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',2600)}
function modal(html,label='AX CONNECT'){ $('#modalLabel').textContent=label;$('#modalBody').innerHTML=html;$('#modal').showModal() }$('#closeModal').onclick=()=>$('#modal').close();$('#modal').addEventListener('click',e=>{if(e.target===$('#modal'))$('#modal').close()});
function render(){ $('#roles').innerHTML=roles.map(([r,i])=>`<button class="role ${r===role?'selected':''}" data-role="${r}"><span>${i}</span>${r}</button>`).join('');document.querySelectorAll('[data-role]').forEach(b=>b.onclick=()=>{role=b.dataset.role;render()});const list=agents.filter(a=>(role==='전체'||a.role===role)&&(!onlyFav||favorites.includes(a.id))&&`${a.name} ${a.role} ${a.desc}`.includes(query));$('#toolCount').textContent=String(list.length).padStart(2,'0');$('#empty').hidden=!!list.length;$('#cards').innerHTML=list.map(a=>`<article class="card"><div class="card-top"><span class="icon">${a.icon}</span><span class="tag">${safe(a.role)} · ${a.local?'내 등록':'샘플 에이전트'}</span><button class="favorite" data-fav="${a.id}" aria-label="${safe(a.name)} 즐겨찾기" aria-pressed="${favorites.includes(a.id)}">${favorites.includes(a.id)?'★':'☆'}</button></div><h3>${safe(a.name)}</h3><p>${safe(a.desc)}</p><div class="card-bottom"><span>${safe(a.owner)} · ${a.local?'이 브라우저에 저장':'활용 제안'}</span><button data-agent="${a.id}">${a.local?'상세 보기':'체험하기'} ↗</button></div></article>`).join('');document.querySelectorAll('[data-fav]').forEach(b=>b.onclick=()=>{let id=Number(b.dataset.fav);favorites=favorites.includes(id)?favorites.filter(x=>x!==id):[...favorites,id];save('j-ax-favs',favorites);render()});document.querySelectorAll('[data-agent]').forEach(b=>b.onclick=()=>openAgent(Number(b.dataset.agent)));$('#allTools').classList.toggle('selected',!onlyFav);$('#favTools').classList.toggle('selected',onlyFav)}
function setView(v){view=v;$('#homeView').hidden=!['home','tools'].includes(v);$('#communityView').hidden=!['home','community'].includes(v);$('#roadmapView').hidden=v!=='roadmap';$('.roles').hidden=v==='tools';document.querySelectorAll('.nav').forEach(b=>b.classList.toggle('active',b.dataset.view===v));if(v==='tools')$('#toolSection').scrollIntoView({behavior:'smooth',block:'start'})}
document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>setView(b.dataset.view));$('#searchForm').onsubmit=e=>{e.preventDefault();query=$('#search').value.trim();role='전체';onlyFav=false;setView('tools');render()};document.querySelectorAll('[data-search]').forEach(b=>b.onclick=()=>{$('#search').value=b.dataset.search;$('#searchForm').requestSubmit()});$('#allTools').onclick=()=>{onlyFav=false;render()};$('#favTools').onclick=()=>{onlyFav=true;render()};
function openAgent(id){const a=agents.find(x=>x.id===id);modal(`<h2>${safe(a.name)}</h2><p class="modal-desc">${safe(a.desc)}</p><span class="local-tag">${a.local?'직원 등록 데모 · 실행 기능 미연결':'샘플 체험 · 실제 AI 호출 없음'}</span><label class="field" for="agentInput">업무 요청</label><textarea class="control" id="agentInput" placeholder="민감정보 없이 체험용 요청을 입력해 주세요">${safe(a.sample||'')}</textarea><div class="actions"><button class="primary" id="runAgent">샘플 결과 보기 ✧</button></div><p class="small-note">입력은 외부로 전송되지 않으며, 결과는 미리 작성된 예시입니다.</p><div id="agentResult" hidden></div>`);$('#runAgent').onclick=()=>{const input=$('#agentInput').value.trim();if(!input){toast('체험할 요청을 입력해 주세요.');return}$('#agentResult').hidden=false;$('#agentResult').className='result';$('#agentResult').textContent='체험 요청: '+input+'\n\n'+(a.result||'이 에이전트는 등록 정보만 저장된 상태입니다. 실제 운영 시 실행 흐름과 AI 연결을 추가합니다.')+'\n\n※ 입력을 AI로 분석한 결과가 아닌 고정 샘플입니다.'}}
function renderPosts(){ $('#posts').innerHTML=posts.map((p,i)=>`<article class="post" tabindex="0" role="button" data-post="${i}"><span class="post-index">${String(i+1).padStart(2,'0')}</span><div><h3>${safe(p.title)}</h3><small>${safe(p.type)} · ${safe(p.team)} · ${p.local?'내 브라우저 저장':'샘플 콘텐츠'}</small></div><span class="arrow">↗</span></article>`).join('');document.querySelectorAll('[data-post]').forEach(el=>{const open=()=>{let p=posts[+el.dataset.post];modal(`<h2>${safe(p.title)}</h2><p class="small-note">${safe(p.type)} · ${safe(p.team)}</p><div class="result">${safe(p.body)}</div>`,'AX EXPERIENCE')};el.onclick=open;el.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();open()}}})}
function addPost(){modal(`<h2>나의 AX 경험 공유</h2><p class="small-note">등록 체험입니다. 이 브라우저에만 저장되며 다른 방문자와 공유되지 않습니다.</p><form id="postForm"><label class="field">제목<input class="control" name="title" required maxlength="80"></label><label class="field">직군<select class="control" name="team">${roles.filter(([name])=>name!=='전체').map(x=>`<option>${x[0]}</option>`).join('')}</select></label><label class="field">어떤 경험을 공유하고 싶나요?<textarea class="control" name="body" required maxlength="3000"></textarea></label><button class="primary">이 브라우저에 등록</button></form>`);$('#postForm').onsubmit=e=>{e.preventDefault();const d=new FormData(e.target);posts.unshift({title:d.get('title'),team:d.get('team'),body:d.get('body'),type:'경험 공유',local:true});save('j-ax-posts',posts.filter(p=>p.local));renderPosts();$('#modal').close();toast('경험을 이 브라우저에 저장했습니다.')}}$('#addPost').onclick=addPost;$('#shareExperience').onclick=addPost;
$('#addAgent').onclick=()=>{modal(`<h2>우리 팀의 에이전트 등록</h2><p class="small-note">등록 정보만 이 브라우저에 저장됩니다. 실제 공유·배포는 정식 구축 이후 가능합니다.</p><form id="agentForm"><label class="field">에이전트 이름<input class="control" name="name" required maxlength="50"></label><label class="field">직군<select class="control" name="role">${roles.filter(([name])=>name!=='전체').map(x=>`<option>${x[0]}</option>`).join('')}</select></label><label class="field">어떤 업무를 돕나요?<textarea class="control" name="desc" required maxlength="250"></textarea></label><button class="primary">등록 체험하기</button></form>`);$('#agentForm').onsubmit=e=>{e.preventDefault();const d=new FormData(e.target);agents.push({id:Date.now(),name:d.get('name'),role:d.get('role'),desc:d.get('desc'),icon:'✧',owner:d.get('role'),local:true});save('j-ax-agents',agents.filter(a=>a.local));role='전체';query='';$('#search').value='';onlyFav=false;render();$('#modal').close();toast('에이전트 정보를 이 브라우저에 등록했습니다.')}};
$('#feedback').onclick=()=>{const f=read('j-ax-feedback',{});modal(`<h2>더 나은 AX를 위한 의견</h2><p class="modal-desc">유용한 기능과 먼저 개선하고 싶은 업무를 알려주세요.</p><p class="small-note">의견은 운영자에게 전송되지 않습니다. 작성 후 내려받은 파일을 담당자에게 전달해 주세요.</p><form id="feedbackForm"><label class="field">우선 검토 기능<select class="control" name="priority"><option>직군별 AI 도구</option><option>에이전트 공유</option><option>AX 경험 커뮤니티</option><option>사내 시스템 연동</option></select></label><label class="field">검토 의견<textarea class="control" name="comment" required maxlength="3000">${safe(f.comment||'')}</textarea></label><div class="actions"><button class="primary" type="submit">의견 저장 및 다운로드 ↓</button></div></form>`,'REVIEW & FEEDBACK');if(f.priority)$('#feedbackForm select').value=f.priority;$('#feedbackForm').onsubmit=e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.target));save('j-ax-feedback',d);const blob=new Blob(['J.ESTINA AX Connect 검토 의견\n\n우선 검토 기능: '+d.priority+'\n\n'+d.comment],{type:'text/plain;charset=utf-8'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='JESTINA-AX-feedback.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);toast('파일을 내려받았습니다. 담당자에게 전달해 주세요.')}};
render();renderPosts();
